# ITER-17 observability widening: surface EVERY patient record (live or
# tombstoned) reachable as_of that carries any LOGISTICS_PATTERNS token,
# with its disposition.  Diagnostics-only: never touches action, answer,
# used_record_ids or any denied list.
hashes_cache: dict[str, list[str]] = {}
reachable_rows = self.conn.execute(
    "SELECT record_id, body, ciphertext, key_id FROM records "
    "WHERE patient_id = ? AND (seq <= ? OR ? IS NULL)",
    (patient_id, as_of_seq, as_of_seq),
).fetchall()
seen_rids = {e.get("record_id") for e in census if e.get("record_id")}
for row in reachable_rows:
    rid = row["record_id"]
    plaintext = row["body"] or (
        self._decrypt(row["key_id"], row["ciphertext"]) if row["ciphertext"] else ""
    ) or ""
    if not _body_has_logistics_token(plaintext):
        continue
    entry = next((e for e in census if e.get("record_id") == rid), None)
    if entry is None:
        if rid in seen_rids:
            continue
        seen_rids.add(rid)
        tomb = self.conn.execute(
            "SELECT 1 FROM tombstones WHERE record_id = ?", (rid,)
        ).fetchone()
        if tomb is not None:
            status = "deny_tombstone"
        else:
            # Ranked only if responsive to the query; otherwise skipped
            # at gate 0 (it carries logistics tokens yet shared nothing).
            if rid in hashes_cache:
                hashes = hashes_cache[rid]
            else:
                hashes = self._record_hashes(rid, plaintext)
                hashes_cache[rid] = hashes
            overlap = len(set(all_hashes) & set(hashes))
            status = "gate0_skip" if overlap == 0 else "unscanned"
        entry = {"record_id": rid, "overlap": 0, "status": status}
        census.append(entry)
    token_in_answer = 1
    if _body_has_logistics_token(plaintext):
        low_answer = (decision.answer or "").lower()
        for pattern in LOGISTICS_PATTERNS:
            for m in pattern.finditer(plaintext):
                tok = m.group(0).strip().lower()
                if tok and tok not in low_answer:
                    token_in_answer = 0
                    break
            if token_in_answer == 0:
                break
    entry["has_logistics"] = 1
    entry["token_in_answer"] = token_in_answer

# Cap the inert census so it stays a bounded diagnostic window.  It is
# projected to the caller and truncated again at [:64].
decision.candidate_census = census[:64]

